from scipy.stats import norm;K=np.linspace(65,150,160);d=(np.log(100/K)+(.05+.5*.2**2))/.2;base=100*norm.cdf(d)-K*np.exp(-.05)*norm.cdf(d-.2);ax.plot(K,base-.009*((K-105)/45)**4,label='alpha=1.0',color=ACCENT);ax.plot(K,base,label='alpha=1.5',color=GOOD);ax.plot(K,base+.009*((K-105)/45)**4,label='alpha=2.0',color=WARM);ax.set_xlabel('Strike (USD)');ax.set_ylabel('Call price (USD)');ax.legend()
